1	// Live-mode orchestration: one request in, one typed { httpStatus, body } out.
2	// Order: validate, rate limit, kill switch, reserve a run, then run in the
3	// mode the code is bound to. Fails closed. Never logs. Bodies carry fixed
4	// messages only: no keys, codes, upstream text, stack traces or company data.
5	
6	import type { LlmClient } from "../../core/agent/llm";
7	import { runImprovedPipeline } from "../../core/agent/improved-pipeline";
8	import type { IcpInput, PipelineResult } from "../../core/agent/types";
9	import { BudgetGuard, type BudgetSnapshot, type CompanyProvider } from "../../core/data/provider";
10	import { DEFAULT_RUN_CONFIG, type RunConfig } from "../../core/types";
11	import { type ProspectDto, type ResultsDto, toResultsDto } from "../../app/results/_lib/presentation";
12	import {
13	  type SyntheticDependencies,
14	  loadSyntheticResults,
15	  syntheticDependencies,
16	} from "../../app/results/_lib/synthetic-run";
17	import { hashCode, hashIp } from "./codes";
18	import type { LiveKeys } from "./config";
19	import { type CodeMode, type LiveStore, type RunOutcome } from "./store";
20	import { type ValidRequest, validateRequest } from "./validate";
21	
22	const IP_WINDOW_SECONDS = 60;
23	const IP_LIMIT = 20;
24	const BAD_CODE_WINDOW_SECONDS = 900;
25	const BAD_CODE_LIMIT = 5;
26	const RUN_LOCK_SECONDS = 330;
27	
28	export const LIVE_RUN_CONFIG: RunConfig = {
29	  ...DEFAULT_RUN_CONFIG,
30	  max_search_results: 10,
31	  max_enrichments: 5,
32	  model: "claude-haiku",
33	  max_llm_calls_per_run: 20,
34	  max_output_tokens_per_call: 1500,
35	};
36	
37	export const LIVE_SEARCH_SORT = { field: "crustdata_company_id", order: "asc" } as const;
38	
39	export const SYNTHETIC_NOTICES: readonly string[] = [
40	  "Synthetic demo: fixture companies and a fake model; your search criteria were not used.",
41	  "One outreach draft deliberately contains an injected unsupported number so you can see the claim check suppress it.",
42	];
43	
44	// ---- Response contract ----------------------------------------------------
45	
46	export interface Usage {
47	  readonly runsRemaining: number;
48	  readonly searched: number;
49	  readonly enriched: number;
50	  readonly providerCostUsd: number;
51	}
52	
53	// The presentation DTO is typed for the synthetic page; a live result differs
54	// in mode, fact provenance and spend, so those fields are widened here.
55	export type LiveResults =
56	  | ResultsDto
57	  | (Omit<ResultsDto, "mode" | "run"> & {
58	      readonly mode: "live";
59	      readonly run: {
60	        readonly status: ResultsDto["run"]["status"];
61	        readonly fact_provider: "crustdata";
62	        readonly limits: ResultsDto["run"]["limits"];
63	        readonly counts: ResultsDto["run"]["counts"];
64	      };
65	    });
66	
67	export type LiveBody =
68	  | {
69	      readonly status: "ok";
70	      readonly mode: CodeMode;
71	      readonly results: LiveResults;
72	      readonly usage: Usage;
73	      readonly notices: readonly string[];
74	    }
75	  | { readonly status: "invalid_request"; readonly field: string; readonly message: string }
76	  | { readonly status: "rate_limited"; readonly retryAfterSeconds: number; readonly message: string }
77	  | { readonly status: "live_disabled"; readonly message: string }
78	  | { readonly status: "invalid_code"; readonly message: string }
79	  | { readonly status: "no_runs_left"; readonly message: string }
80	  | { readonly status: "run_in_progress"; readonly message: string }
81	  | { readonly status: "budget_exhausted"; readonly message: string }
82	  | { readonly status: "run_failed"; readonly message: string }
83	  | { readonly status: "live_unavailable"; readonly message: string };
84	
85	export interface LiveOutcome {
86	  readonly httpStatus: 200 | 400 | 401 | 403 | 409 | 429 | 502 | 503;
87	  readonly body: LiveBody;
88	}
89	
90	const MESSAGES = {
91	  live_disabled: "Live runs are switched off right now.",
92	  invalid_code: "That invite code is not valid.",
93	  no_runs_left: "This invite code has no runs left.",
94	  run_in_progress: "A run is already in progress for this code. Try again shortly.",
95	  budget_exhausted: "The data budget for live runs is used up. Please try again later.",
96	  run_failed: "The run failed. Please try again later.",
97	  live_unavailable: "Live mode is unavailable right now. Please try again later.",
98	  rate_limited: "Too many requests. Please wait before trying again.",
99	  industry_unmatched: "We could not match that industry. Try a broader term.",
100	} as const;
101	
102	const ISSUE_NOTICES: Readonly<Record<string, string | undefined>> = {
103	  enrich_partial: "Some companies could not be enriched, so those use basic search data only.",
104	  enrich_no_results: "No companies could be enriched, so results use basic search data only.",
105	  enrich_failed: "Enrichment failed, so results use basic search data only.",
106	  enrich_budget_exhausted: "The enrichment budget was reached before every company was enriched.",
107	  search_no_match: "No companies matched your criteria.",
108	  search_budget_exhausted: "The search budget was reached.",
109	  llm_call_cap_reached: "The model-call limit was reached, so some companies were not assessed.",
110	  llm_stopped: "Assessment stopped early after a model error, so some companies were not assessed.",
111	  llm_cost_incomplete: "Model cost for this run could not be fully measured.",
112	};
113	
114	const GENERIC_ISSUE = "A step of the run reported a problem.";
115	
116	const FAILED_ASSESSMENT_MESSAGES: Readonly<Record<string, string | undefined>> = {
117	  llm_error: "The model could not assess this company.",
118	  malformed_output: "The model's answer could not be read.",
119	  truncated: "The model's answer was cut off.",
120	  invalid_assessment: "The model's assessment failed the checks.",
121	};
122	
123	// Live DTOs carry text the pipeline copied from model or provider errors.
124	// Replace it with fixed strings so no upstream text reaches the response.
125	function scrubProspect(p: ProspectDto): ProspectDto {
126	  if (p.assessment.status !== "failed") return p;
127	  return {
128	    ...p,
129	    assessment: {
130	      ...p.assessment,
131	      message: FAILED_ASSESSMENT_MESSAGES[p.assessment.reason] ?? "The assessment failed.",
132	    },
133	  };
134	}
135	
136	function respond(httpStatus: LiveOutcome["httpStatus"], body: LiveBody): LiveOutcome {
137	  return { httpStatus, body };
138	}
139	
140	const simple = (
141	  httpStatus: LiveOutcome["httpStatus"],
142	  status:
143	    | "live_disabled"
144	    | "invalid_code"
145	    | "no_runs_left"
146	    | "run_in_progress"
147	    | "budget_exhausted"
148	    | "run_failed"
149	    | "live_unavailable",
150	): LiveOutcome => respond(httpStatus, { status, message: MESSAGES[status] });
151	
152	// For callers that fail before runLive (e.g. configuration is missing).
153	export const liveUnavailable = (): LiveOutcome => simple(503, "live_unavailable");
154	
155	function rateLimited(retryAfterSeconds: number): LiveOutcome {
156	  const seconds = Number.isFinite(retryAfterSeconds) ? Math.max(1, Math.ceil(retryAfterSeconds)) : 60;
157	  return respond(429, { status: "rate_limited", retryAfterSeconds: seconds, message: MESSAGES.rate_limited });
158	}
159	
160	function noticesFromIssues(issues: readonly { readonly code: string }[]): string[] {
161	  const out: string[] = [];
162	  for (const issue of issues) {
163	    const text = ISSUE_NOTICES[issue.code];
164	    if (text !== undefined && !out.includes(text)) out.push(text);
165	  }
166	  return out;
167	}
168	
169	// ---- Dependencies -----------------------------------------------------------
170	
171	export interface LiveProviderBundle {
172	  readonly provider: CompanyProvider;
173	  readonly budget: { snapshot(): BudgetSnapshot };
174	}
175	
176	export interface LiveDeps {
177	  readonly store: LiveStore;
178	  readonly hmacSecret: string;
179	  // null when live keys are not configured: synthetic codes still run.
180	  readonly live: LiveKeys | null;
181	  readonly now: () => Date;
182	  // Live factories. Never called in synthetic mode.
183	  readonly createProvider: (keys: LiveKeys, config: RunConfig) => LiveProviderBundle | Promise<LiveProviderBundle>;
184	  readonly createLlm: (keys: LiveKeys) => LlmClient | Promise<LlmClient>;
185	  readonly synthetic?: SyntheticDependencies;
186	}
187	
188	// The real factories. SDKs are imported lazily so synthetic runs and unit
189	// tests never load them.
190	export const realFactories: Pick<LiveDeps, "createProvider" | "createLlm"> = {
191	  async createProvider(keys, config) {
192	    const { CrustdataProvider } = await import("../../core/data/crustdata-provider");
193	    const budget = new BudgetGuard(config);
194	    const provider = new CrustdataProvider({
195	      api_key: keys.crustdataApiKey,
196	      budget,
197	      search_sort: LIVE_SEARCH_SORT,
198	    });
199	    return { provider, budget };
200	  },
201	  async createLlm(keys) {
202	    const { createGatewayLlmClient } = await import("../../core/agent/gateway-client");
203	    return createGatewayLlmClient({ apiKey: keys.llmApiKey, baseURL: keys.llmBaseUrl });
204	  },
205	};
206	
207	// ---- Orchestration ----------------------------------------------------------
208	
209	export async function runLive(
210	  request: { readonly code: unknown; readonly icp: unknown },
211	  ip: string,
212	  deps: LiveDeps,
213	): Promise<LiveOutcome> {
214	  const checked = validateRequest(request);
215	  if (!checked.ok) {
216	    return respond(400, { status: "invalid_request", field: checked.field, message: checked.message });
217	  }
218	  const valid = checked.value;
219	
220	  let reserved: { runId: string; runsRemaining: number; mode: CodeMode };
221	  try {
222	    const { store, hmacSecret } = deps;
223	    const ipHash = hashIp(ip, hmacSecret);
224	
225	    const rate = await store.hit(`ip:${ipHash}`, deps.now(), IP_WINDOW_SECONDS, IP_LIMIT);
226	    if (!rate.allowed) return rateLimited(rate.retryAfterSeconds);
227	
228	    if (!(await store.isLiveEnabled())) return simple(503, "live_disabled");
229	
230	    const result = await store.reserveRun(hashCode(valid.code, hmacSecret), deps.now(), RUN_LOCK_SECONDS);
231	    if (!result.ok) {
232	      switch (result.reason) {
233	        case "invalid_code":
234	        case "disabled": {
235	          const bad = await store.hit(`badcode:${ipHash}`, deps.now(), BAD_CODE_WINDOW_SECONDS, BAD_CODE_LIMIT);
236	          if (!bad.allowed) return rateLimited(bad.retryAfterSeconds);
237	          return simple(401, "invalid_code");
238	        }
239	        case "no_runs_left":
240	          return simple(403, "no_runs_left");
241	        case "run_in_progress":
242	          return simple(409, "run_in_progress");
243	        default:
244	          return simple(503, "live_unavailable");
245	      }
246	    }
247	    reserved = { runId: result.runId, runsRemaining: result.runsRemaining, mode: result.mode };
248	  } catch {
249	    return simple(503, "live_unavailable");
250	  }
251	
252	  // From here a run exists: every exit must finish or release it.
253	  const { store } = deps;
254	  const settle = async (op: () => Promise<void>) => {
255	    try {
256	      await op();
257	    } catch {
258	      // The outcome is already decided; a store failure cannot change it.
259	    }
260	  };
261	  const failed = async (outcome: Partial<RunOutcome> = {}): Promise<LiveOutcome> => {
262	    await settle(() =>
263	      store.finishRun(reserved.runId, {
264	        status: "failed",
265	        searched: 0,
266	        enriched: 0,
267	        providerCostUsd: 0,
268	        modelCostUsd: 0,
269	        errorCategory: "run_failed",
270	        ...outcome,
271	      }),
272	    );
273	    return simple(502, "run_failed");
274	  };
275	
276	  try {
277	    return reserved.mode === "synthetic"
278	      ? await runSynthetic(reserved, deps, failed)
279	      : await runLiveMode(valid, reserved, deps, failed);
280	  } catch {
281	    return failed();
282	  }
283	}
284	
285	interface Reserved {
286	  readonly runId: string;
287	  readonly runsRemaining: number;
288	  readonly mode: CodeMode;
289	}
290	
291	type Failed = (outcome?: Partial<RunOutcome>) => Promise<LiveOutcome>;
292	
293	async function runSynthetic(reserved: Reserved, deps: LiveDeps, failed: Failed): Promise<LiveOutcome> {
294	  const loaded = await loadSyntheticResults("synthetic", deps.synthetic ?? syntheticDependencies);
295	  if (loaded.kind !== "ok") return failed();
296	  const { results } = loaded;
297	  const searched = results.run.counts.searched;
298	  const enriched = results.run.counts.enriched;
299	  await deps.store.finishRun(reserved.runId, {
300	    status: "completed",
301	    searched,
302	    enriched,
303	    providerCostUsd: 0,
304	    modelCostUsd: 0,
305	  });
306	  const notices = [...SYNTHETIC_NOTICES, ...noticesFromIssues(results.issues)];
307	  return respond(200, {
308	    status: "ok",
309	    mode: "synthetic",
310	    results,
311	    usage: { runsRemaining: reserved.runsRemaining, searched, enriched, providerCostUsd: 0 },
312	    notices,
313	  });
314	}
315	
316	async function runLiveMode(
317	  valid: ValidRequest,
318	  reserved: Reserved,
319	  deps: LiveDeps,
320	  failed: Failed,
321	): Promise<LiveOutcome> {
322	  const { store } = deps;
323	  const release = async (): Promise<LiveOutcome> => {
324	    try {
325	      await store.releaseRun(reserved.runId);
326	    } catch {
327	      // Nothing more can be done; the lock expires on its own.
328	    }
329	    return simple(502, "run_failed");
330	  };
331	
332	  // Before the first paid call: any failure gives the run back.
333	  let bundle: LiveProviderBundle;
334	  let llm: LlmClient;
335	  let industry: string;
336	  const notices: string[] = [];
337	  try {
338	    if (deps.live === null) return await release();
339	    bundle = await deps.createProvider(deps.live, LIVE_RUN_CONFIG);
340	    llm = await deps.createLlm(deps.live);
341	
342	    const suggestions = await bundle.provider.autocompleteIndustry(valid.icp.industry);
343	    if (!suggestions.ok && suggestions.error.category === "no_match") {
344	      await store.releaseRun(reserved.runId);
345	      return respond(400, {
346	        status: "invalid_request",
347	        field: "industry",
348	        message: MESSAGES.industry_unmatched,
349	      });
350	    }
351	    if (!suggestions.ok || suggestions.data.length === 0) return await release();
352	    industry = suggestions.data[0];
353	    notices.push(`Searched the industry "${industry.slice(0, 80)}", the closest match to what you entered.`);
354	  } catch {
355	    return release();
356	  }
357	
358	  const icp: IcpInput = {
359	    industry,
360	    employee_count_ranges: valid.icp.sizes,
361	    locations: [valid.icp.country],
362	    keywords: [],
363	    excluded_domains: [],
364	  };
365	
366	  let result: PipelineResult;
367	  try {
368	    result = await runImprovedPipeline(
369	      icp,
370	      { provider: bundle.provider, budget: bundle.budget, llm, fact_provider: "crustdata" },
371	      { config: LIVE_RUN_CONFIG },
372	    );
373	  } catch {
374	    const snap = safeSnapshot(bundle.budget);
375	    return failed({
376	      searched: snap.searched,
377	      enriched: snap.enriched,
378	      providerCostUsd: snap.cost_usd,
379	      errorCategory: "pipeline_exception",
380	    });
381	  }
382	
383	  const searched = result.usage.provider.searched;
384	  const enriched = result.usage.provider.enriched;
385	  const providerCostUsd = result.usage.provider.cost_usd;
386	  const modelCostUsd = result.usage.llm_cost.known_usd;
387	
388	  if (result.status === "stopped") {
389	    const exhausted = result.issues.some((i) => i.error_category === "budget_cap_reached");
390	    const outcome: RunOutcome = {
391	      status: exhausted ? "budget_exhausted" : "failed",
392	      searched,
393	      enriched,
394	      providerCostUsd,
395	      modelCostUsd,
396	      errorCategory: exhausted ? "budget_cap_reached" : "pipeline_stopped",
397	    };
398	    try {
399	      await store.finishRun(reserved.runId, outcome);
400	    } catch {
401	      // The response is already decided.
402	    }
403	    return simple(exhausted ? 503 : 502, exhausted ? "budget_exhausted" : "run_failed");
404	  }
405	
406	  const dto = toResultsDto(result);
407	  const results: LiveResults = {
408	    metrics: dto.metrics,
409	    issues: dto.issues.map((i) => ({ code: i.code, message: ISSUE_NOTICES[i.code] ?? GENERIC_ISSUE })),
410	    prospects: dto.prospects.map(scrubProspect),
411	    mode: "live",
412	    run: {
413	      status: dto.run.status,
414	      fact_provider: "crustdata",
415	      limits: dto.run.limits,
416	      counts: dto.run.counts,
417	    },
418	  };
419	
420	  await store.finishRun(reserved.runId, {
421	    status: "completed",
422	    searched,
423	    enriched,
424	    providerCostUsd,
425	    modelCostUsd,
426	  });
427	  return respond(200, {
428	    status: "ok",
429	    mode: "live",
430	    results,
431	    usage: { runsRemaining: reserved.runsRemaining, searched, enriched, providerCostUsd },
432	    notices: [...notices, ...noticesFromIssues(result.issues)],
433	  });
434	}
435	
436	function safeSnapshot(budget: { snapshot(): BudgetSnapshot }): BudgetSnapshot {
437	  try {
438	    return budget.snapshot();
439	  } catch {
440	    return { cost_usd: 0, searched: 0, enriched: 0 };
441	  }
442	}
