1	import { type Mock, describe, expect, it, vi } from "vitest";
2	import { FakeLlmClient } from "../../src/core/agent/fake-llm";
3	import type { LlmClient } from "../../src/core/agent/llm";
4	import { FixtureProvider, type InjectedFailure } from "../../src/core/data/fixture-provider";
5	import type { CompanyProvider } from "../../src/core/data/provider";
6	import { hashCode } from "../../src/server/live/codes";
7	import type { LiveKeys } from "../../src/server/live/config";
8	import {
9	  LIVE_RUN_CONFIG,
10	  LIVE_SEARCH_SORT,
11	  type LiveDeps,
12	  type LiveOutcome,
13	  SYNTHETIC_NOTICES,
14	  liveUnavailable,
15	  runLive,
16	} from "../../src/server/live/run-live";
17	import { LiveStoreUnavailable, type LiveStore } from "../../src/server/live/store";
18	import { FakeLiveStore } from "./fake-live-store";
19	
20	const SECRET = "hmac-secret-for-tests-0123456789abcdef";
21	const KEYS: LiveKeys = {
22	  crustdataApiKey: "crust-key-AAAA1111",
23	  llmApiKey: "llm-key-BBBB2222",
24	  llmBaseUrl: "https://llm.example.test/v1",
25	};
26	const CODE = "SYNT-CODE-0001-ABCD";
27	const LIVE_CODE = "LIVE-CODE-0002-EFGH";
28	const T0 = new Date("2026-01-01T00:00:00Z");
29	const ICP = { industry: "Staffing", country: "India", sizes: ["11-50", "51-200"] };
30	const IP = "203.0.113.9";
31	
32	interface Harness {
33	  store: FakeLiveStore;
34	  deps: LiveDeps;
35	  createProvider: Mock<LiveDeps["createProvider"]>;
36	  createLlm: Mock<LiveDeps["createLlm"]>;
37	  autocomplete: Mock<(query: string) => void>;
38	}
39	
40	interface Options {
41	  failures?: InjectedFailure[];
42	  suggestions?: readonly string[] | "no_match" | "failed";
43	  dropOneEnriched?: boolean;
44	  live?: LiveKeys | null;
45	  createProviderThrows?: boolean;
46	}
47	
48	// A fixture-backed stand-in for the Crustdata provider: its autocomplete is
49	// scripted, and searches ignore the filters so the fixtures always match.
50	function liveProvider(options: Options, autocomplete: Mock<(query: string) => void>) {
51	  const inner = new FixtureProvider({
52	    config: LIVE_RUN_CONFIG,
53	    cost_per_record: { search: 0.069, enrich: 0.6 },
54	    failures: options.failures,
55	  });
56	  const provider: CompanyProvider = {
57	    async autocompleteIndustry(query) {
58	      autocomplete(query);
59	      const s = options.suggestions ?? ["Staffing and Recruiting"];
60	      if (s === "no_match") return { ok: false, error: { category: "no_match", message: "none" } };
61	      if (s === "failed") return { ok: false, error: { category: "timeout", message: "upstream said KEY" } };
62	      return { ok: true, data: s, cost_usd: 0, calls: 1 };
63	    },
64	    searchCompanies: (_f, limit) =>
65	      inner.searchCompanies({ country: "", industries: [], employee_count_ranges: [] }, limit),
66	    async enrichCompanies(urls) {
67	      const res = await inner.enrichCompanies(urls);
68	      if (res.ok && options.dropOneEnriched) return { ...res, data: res.data.slice(0, -1) };
69	      return res;
70	    },
71	  };
72	  return { provider, budget: inner.budget };
73	}
74	
75	async function harness(options: Options = {}): Promise<Harness> {
76	  const store = new FakeLiveStore();
77	  await store.setLiveEnabled(true);
78	  await store.admin.createCode("syn", 3, hashCode(CODE, SECRET), "synthetic");
79	  await store.admin.createCode("live", 3, hashCode(LIVE_CODE, SECRET), "live");
80	  const autocomplete = vi.fn<(query: string) => void>();
81	  const createProvider = vi.fn<LiveDeps["createProvider"]>((keys, config) => {
82	    expect(config).toEqual(LIVE_RUN_CONFIG);
83	    expect(keys).toEqual(KEYS);
84	    if (options.createProviderThrows) throw new Error(`boom ${keys.crustdataApiKey}`);
85	    return liveProvider(options, autocomplete);
86	  });
87	  const createLlm = vi.fn<LiveDeps["createLlm"]>((): LlmClient => new FakeLlmClient());
88	  const deps: LiveDeps = {
89	    store,
90	    hmacSecret: SECRET,
91	    live: options.live === undefined ? KEYS : options.live,
92	    now: () => T0,
93	    createProvider,
94	    createLlm,
95	  };
96	  return { store, deps, createProvider, createLlm, autocomplete };
97	}
98	
99	const go = (h: Harness, code: unknown = CODE, icp: unknown = ICP, ip = IP): Promise<LiveOutcome> =>
100	  runLive({ code, icp }, ip, h.deps);
101	
102	function expectNoLeaks(outcome: LiveOutcome, extra: string[] = []) {
103	  const text = JSON.stringify(outcome.body);
104	  for (const secret of [SECRET, KEYS.crustdataApiKey, KEYS.llmApiKey, CODE, LIVE_CODE, ...extra]) {
105	    expect(text).not.toContain(secret);
106	  }
107	  expect(text).not.toMatch(/\bat \S+\.(ts|js):\d+/);
108	}
109	
110	type OkBody = Extract<LiveOutcome["body"], { status: "ok" }>;
111	function okBody(out: LiveOutcome): OkBody {
112	  expect(out.body.status).toBe("ok");
113	  return out.body as OkBody;
114	}
115	
116	function onlyRun(h: Harness) {
117	  expect(h.store.runs.size).toBe(1);
118	  return [...h.store.runs.values()][0];
119	}
120	
121	describe("runLive: request validation and limits", () => {
122	  it("returns 400 invalid_request before touching the store", async () => {
123	    const h = await harness();
124	    const hit = vi.spyOn(h.store, "hit");
125	    const out = await go(h, CODE, { ...ICP, country: "Nepal" });
126	    expect(out.httpStatus).toBe(400);
