1	// Request validation for live runs. Pure: no I/O, and a rejected field is
2	// named with a fixed message that never echoes the input.
3	
4	export const ALLOWED_SIZES = ["11-50", "51-200"] as const;
5	export type AllowedSize = (typeof ALLOWED_SIZES)[number];
6	
7	export type InvalidField = "code" | "icp" | "industry" | "country" | "sizes";
8	
9	export const FIELD_MESSAGES: Readonly<Record<InvalidField, string>> = {
10	  code: "Enter your invite code (up to 64 characters).",
11	  icp: "Describe your ideal customer profile.",
12	  industry: "Industry must be 2 to 80 characters.",
13	  country: "Country must be India.",
14	  sizes: "Choose at least one company size: 11-50 or 51-200.",
15	};
16	
17	export interface ValidRequest {
18	  readonly code: string;
19	  readonly icp: {
20	    readonly industry: string;
21	    readonly country: "India";
22	    readonly sizes: readonly AllowedSize[];
23	  };
24	}
25	
26	export type Validation =
27	  | { readonly ok: true; readonly value: ValidRequest }
28	  | { readonly ok: false; readonly field: InvalidField; readonly message: string };
29	
30	function bad(field: InvalidField): Validation {
31	  return { ok: false, field, message: FIELD_MESSAGES[field] };
32	}
33	
34	function isRecord(value: unknown): value is Record<string, unknown> {
35	  return typeof value === "object" && value !== null && !Array.isArray(value);
36	}
37	
38	export function validateRequest(request: { code: unknown; icp: unknown }): Validation {
39	  const { code, icp } = request;
40	  if (typeof code !== "string" || code.trim() === "" || code.length > 64) return bad("code");
41	  if (!isRecord(icp)) return bad("icp");
42	
43	  const industry = icp.industry;
44	  if (typeof industry !== "string") return bad("industry");
45	  const trimmed = industry.trim();
46	  if (trimmed.length < 2 || trimmed.length > 80) return bad("industry");
47	
48	  if (icp.country !== "India") return bad("country");
49	
50	  const sizes = icp.sizes;
51	  if (!Array.isArray(sizes) || sizes.length === 0) return bad("sizes");
52	  if (!sizes.every((s) => (ALLOWED_SIZES as readonly unknown[]).includes(s))) return bad("sizes");
53	  // Canonical order, no duplicates.
54	  const unique = ALLOWED_SIZES.filter((s) => sizes.includes(s));
55	
56	  return { ok: true, value: { code, icp: { industry: trimmed, country: "India", sizes: unique } } };
57	}
